newsource='''def transform(grid):
    """Advance 4s one row downward; a 4 two rows above the 2-barrier also emits diagonal rays."""
    h, w = len(grid), len(grid[0])
    barrier = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if barrier is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    locs = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    for r, c in locs:
        out[r][c] = 0
    for r, c in locs:
        nr = min(r + 1, h - 1)
        if out[nr][c] != 2:
            out[nr][c] = 4
        if r == barrier - 2:
            for dc in (-1, 1):
                rr, cc = nr, c
                while 0 <= rr - 1 < h and 0 <= cc + dc < w:
                    rr -= 1
                    cc += dc
                    if out[rr][cc] != 2:
                        out[rr][cc] = 4
    return out
'''
